import math

r, K, N0 = 0.18, 12000.0, 500.0
f = lambda N: r * N * (1 - N / K)
tam = lambda t: K / (1 + ((K - N0) / N0) * math.exp(-r * t))

def euler(N, h): return N + h * f(N)
def rk4(N, h):
    k1 = f(N); k2 = f(N + h / 2 * k1)
    k3 = f(N + h / 2 * k2); k4 = f(N + h * k3)
    return N + h / 6 * (k1 + 2 * k2 + 2 * k3 + k4)

def kos(adimla, h, T=10.0):
    N = N0
    for _ in range(int(round(T / h))):
        N = adimla(N, h)
    return N

dogru = tam(10.0)
for ad, adimla in (("euler", euler), ("rk4", rk4)):
    onceki = None
    for h in (1.0, 0.5, 0.25):
        hata = abs(dogru - kos(adimla, h))
        oran = "-" if onceki is None else str(round(onceki / hata, 2))
        print(ad, h, round(hata, 6), oran)
        onceki = hata

