TOHUM = 2024
def uret(x):
    return (1103515245 * x + 12345) % (2 ** 31)

YEM, MENZIL, N, ADIM = 60.0, 5.0, 40, 30

x = TOHUM
konum = []
for i in range(N):
    x = uret(x)
    konum.append(round(100.0 * x / 2 ** 31, 3))

def komsu_var(k, i):
    return any(j != i and abs(k[j] - k[i]) <= MENZIL for j in range(len(k)))

for adim in range(ADIM + 1):
    if adim % 10 == 0:
        yakin = sum(1 for p in konum if abs(p - YEM) <= MENZIL)
        print(adim, yakin, round(sum(konum) / N, 3))
    yeni = []
    for i in range(N):
        p = konum[i]
        if komsu_var(konum, i):
            p += 1.0 if p < YEM else (-1.0 if p > YEM else 0.0)
        else:
            x = uret(x)
            p += 1.0 if x % 2 else -1.0
        yeni.append(min(100.0, max(0.0, p)))
    konum = yeni
